def fetch_all_notes(query, page_limit=20):
    all_notes=[]
    page_index=0
    while True:
        resp = apis.simple_note.search_notes(access_token=simple_token, query=query, page_index=page_index, page_limit=page_limit)
        # Determine where note list is in response
        if isinstance(resp, list):
            batch = resp
        elif isinstance(resp, dict):
            # try common keys
            for key in ['notes','results','data','items']:
                if key in resp and isinstance(resp[key], list):
                    batch = resp[key]
                    break
            else:
                batch = []
        else:
            batch=[]
        print('query', query, 'page', page_index, 'batch_type', type(resp).__name__, 'batch_len', len(batch))
        if not batch:
            break
        all_notes.extend(batch)
        page_index += 1
        if page_index>50:
            break
    return all_notes

notes = fetch_all_notes('venmo')
print('total', len(notes))
# print all titles
for n in notes:
    print(n.get('note_id'), n.get('title'), n.get('tags'))

# filter candidates whose title/tags look like venmo/expense/monthly
cands=[]
for n in notes:
    title=(n.get('title') or '').lower()
    tags=' '.join([t.lower() for t in (n.get('tags') or [])])
    if 'venmo' in title or 'venmo' in tags or 'expense' in title or 'expense' in tags or 'monthly' in title or 'monthly' in tags:
        cands.append(n)
print('candidates', len(cands))
for n in cands:
    print('cand', n.get('note_id'), n.get('title'), n.get('tags'))

